	@Test
	void closeDuringMaterializationReleasesActiveScanWithoutWaitingForBuild() throws Exception {
		BlockingScan scan = new BlockingScan();
		QueryEvaluationStep step = step(scan);
		try (var executor = Executors.newFixedThreadPool(2);
				var iteration = step.evaluate(EmptyBindingSet.getInstance())) {
			var worker = executor.submit(iteration::hasNext);
			assertTrue(scan.entered.await(5, TimeUnit.SECONDS), "Materialization scan must start");
			var closer = executor.submit(iteration::close);
			try {
				assertTrue(scan.closed.await(5, TimeUnit.SECONDS), "Cancellation must close the active EXISTS scan");
				closer.get(5, TimeUnit.SECONDS);
				assertFalse(worker.get(5, TimeUnit.SECONDS));
			} finally {
				scan.release.countDown();
				worker.get(5, TimeUnit.SECONDS);
				closer.get(5, TimeUnit.SECONDS);
			}
		}
	}

