	private static void assertCancelledScanDoesNotPoisonReopen(String mode, boolean negated) throws Exception {
		BlockingScan blocked = new BlockingScan();
		AtomicInteger opens = new AtomicInteger();
		QueryEvaluationStep step = step(() -> opens.getAndIncrement() == 0 ? blocked : matchingScan(), mode, negated);
		try (var executor = Executors.newFixedThreadPool(2);
				var iteration = step.evaluate(EmptyBindingSet.getInstance())) {
			var worker = executor.submit(iteration::hasNext);
			try {
				assertTrue(blocked.entered.await(5, TimeUnit.SECONDS));
				var closer = executor.submit(iteration::close);
				try {
					assertTrue(blocked.closed.await(5, TimeUnit.SECONDS));
					closer.get(5, TimeUnit.SECONDS);
					assertFalse(worker.get(5, TimeUnit.SECONDS));
				} finally {
					blocked.release.countDown();
					closer.get(5, TimeUnit.SECONDS);
				}
			} finally {
				blocked.release.countDown();
				worker.get(5, TimeUnit.SECONDS);
			}
		}
		try (var reopened = step.evaluate(EmptyBindingSet.getInstance())) {
			assertEquals(!negated, reopened.hasNext(), "Cancellation must not cache an incomplete negative result");
		}
		assertEquals(2, opens.get());
	}

