	@Test
	void scanReadFailureKeepsCloseFailureSuppressed() {
		IllegalStateException readFailure = new IllegalStateException("read failed");
		IllegalArgumentException closeFailure = new IllegalArgumentException("close failed");
		TrackingScan scan = new TrackingScan(List.of()) {
			@Override
			public boolean hasNext() {
				throw readFailure;
			}

			@Override
			public void close() {
				super.close();
				throw closeFailure;
			}
		};
		try (var iteration = step(scan).evaluate(EmptyBindingSet.getInstance())) {
			assertSame(readFailure, assertThrows(IllegalStateException.class, iteration::hasNext));
			assertEquals(1, readFailure.getSuppressed().length);
			assertSame(closeFailure, readFailure.getSuppressed()[0]);
		}
		assertEquals(1, scan.closes.get());
	}

	@Test
	void concurrentMaterializersPublishOneSharedPartition() throws Exception {
		var cache = new MaterializedExistsFilterIteration.MaterializationCache();
		CountDownLatch entered = new CountDownLatch(2);
		CountDownLatch release = new CountDownLatch(1);
		AtomicInteger opens = new AtomicInteger();
		Function<BindingSet, CloseableIteration<BindingSet>> evaluation = bindings -> {
			opens.incrementAndGet();
			entered.countDown();
			await(release);
			return bindingRows();
		};
		try (var executor = Executors.newFixedThreadPool(2);
				var first = materialized(cache, evaluation, bindingRows());
				var second = materialized(cache, evaluation, bindingRows())) {
			var firstResult = executor.submit(first::hasNext);
			var secondResult = executor.submit(second::hasNext);
			try {
				assertTrue(entered.await(5, TimeUnit.SECONDS),
						"Builders must not hold the shared cache lock during IO");
			} finally {
				release.countDown();
			}
			assertTrue(firstResult.get(5, TimeUnit.SECONDS));
			assertTrue(secondResult.get(5, TimeUnit.SECONDS));
			assertEquals(1, cache.residentRows(), "Concurrent publication must count the winning partition only");
		}
		try (var reused = materialized(cache, evaluation, bindingRows())) {
			assertTrue(reused.hasNext());
		}
		assertEquals(2, opens.get());
	}

