	private static class TrackingScan implements CloseableIteration<Statement> {
		private final Iterator<Statement> rows;
		private final AtomicInteger reads = new AtomicInteger();
		private final AtomicInteger closes = new AtomicInteger();

		private TrackingScan(List<Statement> rows) {
			this.rows = rows.iterator();
		}

		@Override
		public boolean hasNext() {
			reads.incrementAndGet();
			return closes.get() == 0 && rows.hasNext();
		}

		@Override
		public Statement next() {
			return rows.next();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closes.incrementAndGet();
		}
	}

	private static QueryEvaluationStep step(CloseableIteration<Statement> scan) {
		return step(() -> scan, "materialized-hash", false);
	}

	private static QueryEvaluationStep step(Supplier<CloseableIteration<Statement>> scans, String mode,
			boolean negated) {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding("s", VF.createIRI("urn:subject"));
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingSets(List.of(row));
		StatementPattern right = new StatementPattern(Var.of("s"),
				Var.of("predicate", VF.createIRI("urn:predicate"), true, true), Var.of("o"));
		Filter filter = new Filter(left, negated ? new Not(new Exists(right)) : new Exists(right));
		filter.setStringMetricPlanned("optimizer.filterAlgorithmHint", mode);
		filter.setRuntimeTelemetryEnabled(true);
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				return scans.get();
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		return new DefaultEvaluationStrategy(source, null).precompile(filter);
	}

	private static final class BlockingScan implements CloseableIteration<Statement> {
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch closed = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);

		@Override
		public boolean hasNext() {
			entered.countDown();
			try {
				assertTrue(release.await(10, TimeUnit.SECONDS), "Scan must be released by cancellation or cleanup");
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new AssertionError(e);
			}
			return false;
		}

		@Override
		public Statement next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closed.countDown();
			release.countDown();
		}
	}
